def transform(grid):
    """Fill straight gaps between consecutive occurrences of the marker color with 3."""
    out = [row[:] for row in grid]
    h = len(grid)
    w = len(grid[0]) if h else 0
    marker = max((v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid)) if h and w else None
    # The marker is the less frequent non-background color; ARC examples use a
    # uniform background and a sparse set of marker cells.
    if marker is not None:
        counts = {}
        for row in grid:
            for v in row:
                counts[v] = counts.get(v, 0) + 1
        marker = min(counts, key=counts.get)
        for r in range(h):
            positions = [c for c, v in enumerate(grid[r]) if v == marker]
            for a, b in zip(positions, positions[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] != marker:
                        out[r][c] = 3
        for c in range(w):
            positions = [r for r in range(h) if grid[r][c] == marker]
            for a, b in zip(positions, positions[1:]):
                for r in range(a + 1, b):
                    if grid[r][c] != marker:
                        out[r][c] = 3
    return out
